    color: #fff;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ── Empty state ── */
.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #717274;
    font-size: 1rem;
}

/* ── Thread panel ── */
.thread-panel {
    width: 25%;
    min-width: 260px;
    border-left: 1px solid #2c2d30;
    background: #19171d;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-thread-btn {
    background: transparent;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #2c2d30;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    background: #222529;
    border-bottom: 1px solid #2c2d30;
    border-left: 3px solid #1d9bd1;
    margin: 12px;
    border-radius: 4px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-panel .message-input-area {
    padding: 12px 16px;
}
"}

